def sha(p):
    h = hashlib.sha256()
    with p.open('rb') as f:
        for b in iter(lambda : f.read(1048576), b''):
            h.update(b)
    return h.hexdigest()

def run(c, name, timeout=1200):
    start = time.monotonic()
    timedout = False
    with (out / name).open('w') as f:
        p = subprocess.Popen(c, stdout=f, stderr=subprocess.STDOUT, start_new_session=True)
        try:
            p.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            timedout = True
            os.killpg(p.pid, signal.SIGTERM)
            try:
                p.wait(timeout=10)
            except subprocess.TimeoutExpired:
                os.killpg(p.pid, signal.SIGKILL)
                p.wait()
    rc = p.returncode
    (out / (name + '.exit.json')).write_text(json.dumps({'command': c, 'exit': rc, 'seconds': time.monotonic() - start, 'timeout': timedout, 'process_group_killed_on_timeout': timedout}))
    return rc
