    def device_record():
        import stat
        result = {}
        for name in ['dev', 'dev/null', 'dev/zero', 'dev/random', 'dev/urandom', 'dev/tty', 'dev/ptmx', 'dev/pts', 'dev/pts/ptmx', 'dev/shm', 'proc']:
            p = root / name
            try:
                z = p.lstat()
                r = {'type': stat.S_IFMT(z.st_mode), 'mode': oct(stat.S_IMODE(z.st_mode)), 'uid': z.st_uid, 'gid': z.st_gid, 'rdev': z.st_rdev, 'is_char': stat.S_ISCHR(z.st_mode), 'is_regular': stat.S_ISREG(z.st_mode)}
                if stat.S_ISCHR(z.st_mode):
                    r.update(major=os.major(z.st_rdev), minor=os.minor(z.st_rdev))
                if stat.S_ISLNK(z.st_mode):
                    r['link'] = os.readlink(p)
                result[name] = r
            except FileNotFoundError:
                result[name] = {'missing': True}
        return result
